-- Daily self-improvement reports.
-- Apply once in the Supabase SQL editor (same project as zoro_episodes).
--
-- One row per local day. Generated by zoro_reflector at the configured
-- reflection hour (default 23:00 local). The morning briefing reads the
-- most recent unspoken row and speaks it, then marks spoken=true.

create table if not exists zoro_daily_reports (
  id              bigserial primary key,
  created_at      timestamptz not null default now(),
  report_date     date        not null unique,
  summary         text        not null,         -- spoken-friendly paragraph
  top_lesson_ids  jsonb,                         -- ids of lessons included
  needs_resources jsonb,                         -- ["Notion API", ...]
  episode_stats   jsonb,                         -- {"success":N,"error":M,...}
  spoken          boolean     not null default false,
  spoken_at       timestamptz
);

create index if not exists zoro_daily_reports_date_idx
  on zoro_daily_reports (report_date desc);
create index if not exists zoro_daily_reports_unspoken_idx
  on zoro_daily_reports (spoken, report_date desc);
